mapper.select:
SELECT id AS sourceId,projectId AS originalProjectId,barcode,itemCode,itemModel,itemName, receiveName,emsNum,emsCompany,packdate,contractNo,installAddress, JSON_OBJECT('fallbackLocation',installAddress) AS locationSnapshot, chProjectId,chContractNo,transferProjectId,transferContractNo,transferFlag, CASE WHEN transferFlag='-1' AND chProjectId IS NULL AND chContractNo IS NULL AND transferProjectId IS NULL AND transferContractNo IS NULL THEN 0 ELSE 1 END AS transferPending, createTime,createBy AS source_creator,updateTime,updateBy AS source_updater FROM pm_project_shipment
WHERE projectId IN #{key}
WHERE 1=0
ORDER BY id LIMIT #{limit}
